WITH scored AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY paid_at, id) AS row_seq, CUME_DIST() OVER (PARTITION BY method, order_id ORDER BY amount DESC) AS amount_cume_dist, AVG(amount) OVER (PARTITION BY status ORDER BY amount, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS amount_avg_5_prior FROM payments), base AS (SELECT *, amount_avg_5_prior + amount_cume_dist AS amount_avg_5_prior_plus_amount_cume_dist FROM scored WHERE paid_at >= DATE '2023-05-31' AND order_id IS NOT NULL), joined AS (SELECT src.id, src.order_id, src.method, src.amount, src.paid_at, src.status, src.row_seq, src.amount_cume_dist, src.amount_avg_5_prior, src.amount_avg_5_prior_plus_amount_cume_dist, p.order_date, p.shipping_fee, p.channel FROM base src INNER JOIN orders p ON src.order_id = p.id WHERE p.discount < 0.15), remaining_keys AS (SELECT id FROM joined EXCEPT SELECT id FROM payments WHERE order_id IN (17, 18)), kept_rows AS (SELECT s.* FROM joined s INNER JOIN remaining_keys k ON s.id = k.id), cleaned AS (SELECT id, order_id, method, amount, paid_at, status, row_seq, amount_cume_dist, amount_avg_5_prior, amount_avg_5_prior_plus_amount_cume_dist, order_date, shipping_fee, channel, CASE WHEN amount >= 1410 THEN 'High' WHEN amount >= 720 THEN 'Medium' ELSE 'Low' END AS amount_level FROM kept_rows WHERE amount_cume_dist BETWEEN 0.56 AND 0.77), enriched AS (SELECT *, DENSE_RANK() OVER (ORDER BY amount_avg_5_prior DESC NULLS LAST) AS amount_avg_5_prior_dense_rank, AVG(amount_avg_5_prior) OVER (PARTITION BY order_id) AS order_id_avg_amount_avg_5_prior FROM cleaned), matched AS (SELECT a.*, pr.id AS promo_id, pr.promo_code, pr.discount_pct FROM enriched a INNER JOIN promotions pr ON a.channel <=> pr.channel AND a.paid_at >= pr.starts_on AND a.paid_at < pr.ends_on + INTERVAL '30' DAY) SELECT s.id, s.order_id, s.method, s.status, s.row_seq, s.amount_cume_dist, s.amount_avg_5_prior_plus_amount_cume_dist, s.channel, s.amount_level, CASE WHEN status RLIKE '^(SUCCESS|REFUNDED)$' THEN 'GROUP_B' WHEN status RLIKE '^(FAILED)$' THEN 'PRIORITY' ELSE 'OTHER_ZONE' END AS status_zone, (SELECT MAX(s2.cost) FROM shipments s2 WHERE s2.order_id = s.order_id) AS max_shipment_cost FROM matched s ORDER BY channel DESC NULLS LAST;
